import raw from '../assets/soft-tissues.json'

/**
 * Muscles, joints and muscular insertions exported from Z-Anatomy, named from TA2
 * (assets/soft-tissues.json, generated by tools/anatomy/gen-soft-tissues.mjs). Each entry is
 * a node of muscles.glb, joints.glb or insertions.glb.
 */
export type SoftSet = 'muscles' | 'joints' | 'insertions'
export type Side = 'left' | 'right'

export interface SoftGroup {
  en: string
  es: string | null
}

export interface SoftEntry {
  set: SoftSet
  id: string
  /** Muscles: 'muscle' | 'fascia' | 'bursa' | 'sheath'. Joints: 'ligament' | 'articular capsule' | 'cartilage'…
   *  Insertions: 'origin' | 'insertion'. */
  kind: string
  side: Side | null
  en: string
  la: string | null
  es: string | null
  /** Muscles: the muscle a piece belongs to (a tendon's `of` is its belly). */
  of?: string
  part?: 'belly' | 'tendon'
  /** Muscles and joints: TA groups from the nearest up. */
  groups?: SoftGroup[]
  /** Insertions: the bone it sits on and the muscle pieces it belongs to. */
  bone?: string
  musclePieces?: string[]
  /** Insertions: named after the piece itself (true) or after the whole muscle (false). */
  exact?: boolean
}

export const softEntries = raw as SoftEntry[]
export const softById = new Map(softEntries.map((e) => [e.id, e]))

/** Spanish name, falling back to the TA English name. */
export const softName = (e: SoftEntry) => e.es ?? e.en

/** The muscle a node belongs to: a tendon resolves to its belly. */
export const muscleOf = (id: string): SoftEntry | undefined => {
  const e = softById.get(id)
  return e?.of ? softById.get(e.of) : e
}

/**
 * Origin and insertion areas of each muscle piece. A head of a split muscle keeps its own
 * areas of a kind and inherits the whole muscle's only for the kind it lacks: the
 * sternocostal head of pectoralis major arises from the sternum, not from the clavicle,
 * but ends on the humerus with the rest of the muscle.
 */
export const insertionsOf = new Map<string, SoftEntry[]>()
{
  const own = new Map<string, SoftEntry[]>()
  const inherited = new Map<string, SoftEntry[]>()
  for (const e of softEntries) {
    if (e.set !== 'insertions') continue
    for (const piece of e.musclePieces ?? []) {
      const into = e.exact ? own : inherited
      into.set(piece, [...(into.get(piece) ?? []), e])
    }
  }
  for (const piece of new Set([...own.keys(), ...inherited.keys()])) {
    const mine = own.get(piece) ?? []
    const kinds = new Set(mine.map((e) => e.kind))
    insertionsOf.set(piece, [...mine, ...(inherited.get(piece) ?? []).filter((e) => !kinds.has(e.kind))])
  }
}

/** A short Spanish label for the kind of a joint piece. */
export const jointKindLabel: Record<string, string> = {
  ligament: 'Ligamento',
  'articular capsule': 'Cápsula articular',
  cartilage: 'Fibrocartílago',
  fat: 'Cuerpo adiposo',
}
